def create_roles(apps, schema_editor):
    from careapp.permissions import DEFAULT_ROLES
    Role = apps.get_model('careapp', 'Role')
    RoleAssignment = apps.get_model('careapp', 'RoleAssignment')
    User = apps.get_model(*settings.AUTH_USER_MODEL.split('.'))
    roles = {}
    for name, description, perms, locked in DEFAULT_ROLES:
        roles[name], _ = Role.objects.get_or_create(
            name=name, defaults={'description': description, 'permissions': perms, 'is_locked': locked})
    # Staff who could use the dashboard before roles existed keep full access.
    for user in User.objects.filter(is_staff=True, is_superuser=False):
        RoleAssignment.objects.get_or_create(user=user, defaults={'role': roles['Administrator']})


